  "ei.h.aato": "इसदे कन्नै तैह् होंदा ऐ जे ई-इनवॉइस तुंदे उप्पर लागू ऐ जां नेईं, ते 30 दिनें दी हद्द लागू ऐ जां नेईं। एह् इस्सै ब्राउज़र च याद रौंह्दा ऐ।",
  "ev.hsn6": "आइटम {n}: ई-इनवॉइस च 6 जां 8 अंकें दा HSN/SAC कोड चाहिदा ऐ (4 अंक सिर्फ ₹5 करोड़ थमां घट्ट आह्‌ले बिजनेस आस्तै न, जेह्‌ड़े ई-इनवॉइस नेईं बनांदे)।",
  "ev.old30": "एह् इनवॉइस 30 जां मते दिन पराना ऐ। ₹10 करोड़ जां मते टर्नओवर पर पोर्टल इसगी हून रजिस्टर नेईं करदा। नमां इनवॉइस बनाने थमां पैह्‌लें अपने अकाउंटेंट कोला पुच्छो।",
  "ev.lt5": "ई-इनवॉइस तुंदे आस्तै ज़रूरी नेईं, जिच्चर 2017-18 थमां कुसै साल तुंदा टर्नओवर ₹5 करोड़ पार नेईं होए दा।",
  "ev.old180": "180 दिनें थमां पराने डॉक्यूमैंट दा ई-वे बिल पोर्टल नेईं बनांदा।",
  "ev.smallst": "{st} दे अंदर ई-वे बिल आमतौर उप्पर ₹{v} थमां उप्पर गै चाहिदा ऐ (दूए राज्य च ₹50,000 थमां उप्पर; दूए राज्य जाने आह्‌ले जॉब वर्क ते हैंडीक्राफ्ट उप्पर हर रकम पर चाहिदा)।",
  "ev.fromirn": "जेकर तुंदे बिजनेस गी ई-इनवॉइस बनाना पौंदा ऐ, तां इस इनवॉइस दा ई-वे बिल पोर्टल सिर्फ इसदे IRN थमां बनांदा ऐ: “ई-इनवॉइस कन्नै ई-वे बिल बी बनाओ” पर टिक करो ते ई-इनवॉइस फाइल बनाओ।",
  "ev.tidchk": "ट्रांसपोर्टर ID दा आखरी अक्खर मेल नेईं खंदा। टाइपिंग दी गलती ते नेईं, इक बारी जांची लैओ।",
