  "bk.h.s3e": "जनरेट करने दे बाद पोर्टल थमां नतीजा डाउनलोड करो ते एत्थें चुनो। ई-वे बिल नंबर सेव कीते दे इनवॉइसें उप्पर ते थल्लै दी गड्डी दी फ़ाइल च जंदे न।",
