  "b2.farule1": "खातें दा डेप्रिसिएशन कंपनीज़ एक्ट, 2013 दे शेड्यूल II मताबक ऐ: हर किस्म दे एसेट दी कम्मै दी उमर ऐ (जि'यां कंप्यूटर 3 साल, फर्नीचर 10 साल, प्लांट ते मशीनरी 15 साल, कार 8 साल), बचदी वैल्यू आम तौर उप्पर लागत दे 5% थमां मती नेईं होंदी, ते साल दे बश्कार जोड़े जां बेचे गेदे एसेट पर सिर्फ बरतने आह्ले दिनें दा डेप्रिसिएशन लगदा ऐ। स्ट्रेट लाइन (SLM: हर साल बराबर रकम) जां रिटन डाउन वैल्यू (WDV: बचदी रकम पर तै रेट) चुनो। प्रोपराइटर ते फर्मां अक्सर इयै तरीका अपनांदियां न; फैसला तुंदा अकाउंटेंट करदा ऐ।",
  "b2.farule2": "इनकम टैक्स डेप्रिसिएशन हर ब्लॉक दा बक्खरा कड्ढेआ जंदा ऐ: ब्लॉक रेट पर रिटन डाउन वैल्यू (जि'यां प्लांट ते मशीनरी 15%, फर्नीचर 10%, कंप्यूटर 40%), साल च 180 दिनें थमां घट्ट बरते गेदे एसेट पर अद्धा रेट, ते बिक्री दा पैसा ब्लॉक चा घटदा ऐ। एह् सिर्फ इनकम टैक्स रिटर्न आस्तै ऐ, खातें च कदें नेईं पाया जंदा। भरे दे रेट आम ब्लॉक रेट न: अपने अकाउंटेंट कोला पक्का करो, खास करियै 1 अप्रैल 2026 थमां इनकम-टैक्स एक्ट, 2025 आह्ले सालें आस्तै।",
  "b2.farule3": "डेप्रिसिएशन तुंदे खातें च तां गै जंदा ऐ जिसलै तुस 'डेप्रिसिएशन पाओ' दबांदे ओ: साल दे आखरी दिन (जां साल दे बश्कार अज्ज) दी जर्नल एंट्री डेप्रिसिएशन गी डेबिट करदी ऐ ते हर एसेट घटांदी ऐ। बाद च एसेट बदलो तां फ्ही पाओ, सिर्फ फर्क जुड़ग।",
